cd /tmp; python3 - <<'EOF'
import zipfile, re
z=zipfile.ZipFile('logic.jar')
pat=re.compile(rb'(pkg\.github|maven\.pkg|GITHUB_TOKEN|swcodeGpr|gpr\.user|gpr\.key|github\.com|github')  , re.I)
hits={}
for n in z.namelist():
    if n.endswith(('.class','.properties','.kts','.txt','.xml')):
        try:
            d=z.read(n)
        except Exception: continue
        if pat.search(d):
            hits[n]=pat.findall(d)[:5]
for k,v in list(hits.items())[:30]:
    print(k, v)
print("total", len(hits))
EOF
